import { type NextRequest, NextResponse } from 'next/server'
import { publicBookingCreateRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { createPaymentCheckout } from '@/lib/dodo/checkout'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const BodySchema = z.object({
  booking_token: z.string().min(1).max(128),
})

/**
 * POST /api/public/deposits/checkout
 * Anonymous — creates a Dodo one-time payment checkout for a booking deposit.
 * Rate-limited to 3/min per IP.
 *
 * Client lands here after booking confirmation — clicks "Pay deposit".
 * Returns checkoutUrl to redirect to Dodo hosted checkout.
 */
export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await publicBookingCreateRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'too many requests — try again in a minute' }, { status: 429 })

  const body = BodySchema.safeParse(await req.json().catch(() => ({})))
  if (!body.success) {
    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
  }

  const { booking_token } = body.data

  // Use service-role to look up booking (no auth session on public flow)
  const supabase = createServiceRoleClient()

  const { data: booking } = await supabase
    .from('bookings')
    .select(`
      id, booking_token, studio_id, client_id,
      deposit_paid,
      services(id, name, deposit_cents),
      clients(id, email, first_name),
      studios(id, slug)
    `)
    .eq('booking_token', booking_token)
    .maybeSingle()

  if (!booking) {
    return NextResponse.json({ error: 'booking not found' }, { status: 404 })
  }

  if (booking.deposit_paid) {
    return NextResponse.json({ error: 'deposit already paid' }, { status: 409 })
  }

  const service = booking.services as { id: string; name: string; deposit_cents: number } | null
  if (!service || service.deposit_cents <= 0) {
    return NextResponse.json({ error: 'no deposit required for this booking' }, { status: 400 })
  }

  const client = booking.clients as { id: string; email: string; first_name: string } | null
  const studio = booking.studios as { id: string; slug: string } | null

  // Get studio's Dodo customer ID (if they have a subscription)
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('dodo_customer_id')
    .eq('studio_id', booking.studio_id)
    .maybeSingle()

  const depositProductId = process.env.DODO_PRODUCT_DEPOSIT ?? ''
  if (!depositProductId) {
    logger.error({ studioId: booking.studio_id }, 'DODO_PRODUCT_DEPOSIT env var not set')
    return NextResponse.json({ error: 'deposit payments not configured — contact the studio' }, { status: 500 })
  }

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  const studioSlug = studio?.slug ?? booking.studio_id

import { createClient as createSupabaseClient } from '@supabase/supabase-js'
import type { Database } from './types'

/**
 * Anon Supabase client for public (unauthenticated) routes.
 *
 * Used only in public booking API routes that serve the client-facing booking flow.
 * Does NOT use session cookies — callers are anonymous browsers.
 *
 * RLS still applies via anon role policies (read-only access to public tables).
 * For mutation RPCs, use SECURITY DEFINER functions only.
 */
export function createPublicClient() {
  return createSupabaseClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  )
}

/**
 * Rate limiters — Upstash Ratelimit.
 *
 * Falls back to a permissive no-op limiter when UPSTASH_REDIS_REST_URL /
 * UPSTASH_REDIS_REST_TOKEN are absent (local dev without Redis).
 *
 * Production MUST have both env vars set or all limiters will always allow
 * requests — the startup check in lib/env.ts will warn in that case.
 */
import { logger } from '@/lib/logger'

// ─── Limiter interface (matches Upstash RatelimitResponse shape) ────────────
export interface RateLimitResponse {
  success: boolean
  limit: number
  remaining: number
  reset: number
}

export interface Limiter {
  limit: (identifier: string) => Promise<RateLimitResponse>
}

// ─── No-op fallback (used when Redis env vars absent) ───────────────────────
function makeNoop(name: string): Limiter {
  let warned = false
  return {
    async limit() {
      if (!warned) {
        logger.warn(
          { limiter: name },
          'rate-limit: UPSTASH_REDIS_REST_URL not set — limiter is permissive (dev mode)',
        )
        warned = true
      }
      return { success: true, limit: 9999, remaining: 9999, reset: Date.now() + 60_000 }
    },
  }
}

