-- ============================================================
-- Migration: 20260422100000_flash_events
-- Purpose : Flash day event booking system (Track A, Sprint 4)
-- Tables  : flash_events, flash_event_designs, flash_event_slots
-- Storage : flash-event-assets bucket
-- RLS     : studio_members for staff; anon read for public+published
-- Rollback:
--   DROP TRIGGER IF EXISTS trg_flash_events_updated_at ON flash_events;
--   DROP FUNCTION IF EXISTS generate_flash_event_slots(uuid);
--   DROP FUNCTION IF EXISTS public_reserve_flash_slot(text, uuid, jsonb);
--   DROP TABLE IF EXISTS flash_event_slots;
--   DROP TABLE IF EXISTS flash_event_designs;
--   DROP TABLE IF EXISTS flash_events;
-- ============================================================

-- ── Re-use shared updated_at helper (already defined in 20260420120000_projects) ──
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- ============================================================
-- 1. flash_events
-- ============================================================

CREATE TABLE IF NOT EXISTS flash_events (
  id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id           uuid        NOT NULL REFERENCES studios(id)    ON DELETE CASCADE,
  artist_id           uuid                 REFERENCES artists(id)    ON DELETE SET NULL,
  title               text        NOT NULL,
  slug                text        NOT NULL,  -- URL-friendly, unique per studio
  description         text,
  event_date          date        NOT NULL,
  start_time          time        NOT NULL,
  end_time            time        NOT NULL,
  slot_duration_min   int         NOT NULL CHECK (slot_duration_min BETWEEN 15 AND 480),
  slot_price_cents    int         NOT NULL DEFAULT 0,
  deposit_cents       int         NOT NULL DEFAULT 0,
  currency            text        NOT NULL DEFAULT 'USD',
  max_slots           int,                   -- NULL = unlimited
  cover_image_url     text,
  flyer_url           text,                  -- storage path for flash sheet PDF/image
  location_id         uuid                 REFERENCES locations(id)  ON DELETE SET NULL,
  public              boolean     NOT NULL DEFAULT true,
  status              text        NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft', 'published', 'completed', 'cancelled')),
  published_at        timestamptz,
  cancelled_at        timestamptz,
  created_by          uuid                 REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (studio_id, slug)
);

CREATE TRIGGER trg_flash_events_updated_at
  BEFORE UPDATE ON flash_events
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 2. flash_event_designs
-- ============================================================

CREATE TABLE IF NOT EXISTS flash_event_designs (
  id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  flash_event_id      uuid        NOT NULL REFERENCES flash_events(id) ON DELETE CASCADE,
  title               text        NOT NULL,               -- "Spider Web", "Black Cat"
  image_url           text        NOT NULL,               -- storage path
  size_description    text,                               -- "2 inches"
  placement_options   text,                               -- "forearm, ankle"
  price_cents         int,                                -- NULL = use event price
  display_order       int         NOT NULL DEFAULT 0,
  sold_out            boolean     NOT NULL DEFAULT false,
  created_at          timestamptz NOT NULL DEFAULT now()
);

-- ============================================================
-- 3. flash_event_slots
-- ============================================================

CREATE TABLE IF NOT EXISTS flash_event_slots (
  id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  flash_event_id      uuid        NOT NULL REFERENCES flash_events(id) ON DELETE CASCADE,
  slot_start          timestamptz NOT NULL,
  slot_end            timestamptz NOT NULL,
  status              text        NOT NULL DEFAULT 'open'
                        CHECK (status IN ('open', 'reserved', 'booked', 'blocked')),
  booking_id          uuid                 REFERENCES bookings(id)     ON DELETE SET NULL,
  design_id           uuid                 REFERENCES flash_event_designs(id) ON DELETE SET NULL,
  reserved_until      timestamptz,          -- hold expiry during checkout
  created_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (flash_event_id, slot_start)
);

-- ============================================================
-- 4. Indexes
-- ============================================================

CREATE INDEX IF NOT EXISTS idx_flash_events_studio_date
  ON flash_events(studio_id, event_date DESC);

CREATE INDEX IF NOT EXISTS idx_flash_events_public_published
  ON flash_events(public, status, event_date)
  WHERE public = true AND status = 'published';

CREATE INDEX IF NOT EXISTS idx_flash_event_designs_order
  ON flash_event_designs(flash_event_id, display_order);

CREATE INDEX IF NOT EXISTS idx_flash_event_slots_status
  ON flash_event_slots(flash_event_id, slot_start, status);

CREATE INDEX IF NOT EXISTS idx_flash_event_slots_booking
  ON flash_event_slots(booking_id)
  WHERE booking_id IS NOT NULL;

-- ============================================================
-- 5. RLS
-- ============================================================

ALTER TABLE flash_events        ENABLE ROW LEVEL SECURITY;
ALTER TABLE flash_event_designs ENABLE ROW LEVEL SECURITY;
ALTER TABLE flash_event_slots   ENABLE ROW LEVEL SECURITY;

-- ── flash_events ──────────────────────────────────────────────────────────

-- Studio members: full CRUD on their studio's events
CREATE POLICY "flash_events_studio_member_select"
  ON flash_events FOR SELECT
  USING (
    studio_id IN (
      SELECT sm.studio_id FROM studio_members sm
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
    )
  );

CREATE POLICY "flash_events_studio_member_insert"
  ON flash_events FOR INSERT
  WITH CHECK (
    studio_id IN (
      SELECT sm.studio_id FROM studio_members sm
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin', 'receptionist')
    )
  );

CREATE POLICY "flash_events_studio_member_update"
  ON flash_events FOR UPDATE
  USING (
    studio_id IN (
      SELECT sm.studio_id FROM studio_members sm
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin', 'receptionist')
    )
  );

CREATE POLICY "flash_events_studio_member_delete"
  ON flash_events FOR DELETE
  USING (
    studio_id IN (
      SELECT sm.studio_id FROM studio_members sm
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin')
    )
  );

-- Public anon: read-only on public+published events
CREATE POLICY "flash_events_public_read"
  ON flash_events FOR SELECT
  USING (public = true AND status = 'published');

-- ── flash_event_designs ───────────────────────────────────────────────────

CREATE POLICY "flash_event_designs_studio_member_select"
  ON flash_event_designs FOR SELECT
  USING (
    flash_event_id IN (
      SELECT fe.id FROM flash_events fe
      INNER JOIN studio_members sm ON sm.studio_id = fe.studio_id
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
    )
  );

CREATE POLICY "flash_event_designs_studio_member_insert"
  ON flash_event_designs FOR INSERT
  WITH CHECK (
    flash_event_id IN (
      SELECT fe.id FROM flash_events fe
      INNER JOIN studio_members sm ON sm.studio_id = fe.studio_id
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin', 'receptionist')
    )
  );

CREATE POLICY "flash_event_designs_studio_member_update"
  ON flash_event_designs FOR UPDATE
  USING (
    flash_event_id IN (
      SELECT fe.id FROM flash_events fe
      INNER JOIN studio_members sm ON sm.studio_id = fe.studio_id
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin', 'receptionist')
    )
  );

CREATE POLICY "flash_event_designs_studio_member_delete"
  ON flash_event_designs FOR DELETE
  USING (
    flash_event_id IN (
      SELECT fe.id FROM flash_events fe
      INNER JOIN studio_members sm ON sm.studio_id = fe.studio_id
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin', 'receptionist')
    )
  );

-- Public anon: read designs of public+published events
CREATE POLICY "flash_event_designs_public_read"
  ON flash_event_designs FOR SELECT
  USING (
    flash_event_id IN (
      SELECT id FROM flash_events WHERE public = true AND status = 'published'
    )
  );

-- ── flash_event_slots ─────────────────────────────────────────────────────

CREATE POLICY "flash_event_slots_studio_member_select"
  ON flash_event_slots FOR SELECT
  USING (
    flash_event_id IN (
      SELECT fe.id FROM flash_events fe
      INNER JOIN studio_members sm ON sm.studio_id = fe.studio_id
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
    )
  );

CREATE POLICY "flash_event_slots_studio_member_update"
  ON flash_event_slots FOR UPDATE
  USING (
    flash_event_id IN (
      SELECT fe.id FROM flash_events fe
      INNER JOIN studio_members sm ON sm.studio_id = fe.studio_id
      WHERE sm.profile_id = auth.uid() AND sm.deactivated_at IS NULL
        AND sm.role IN ('owner', 'admin', 'receptionist')
    )
  );

-- Public anon: read slots of public+published events
CREATE POLICY "flash_event_slots_public_read"
  ON flash_event_slots FOR SELECT
  USING (
    flash_event_id IN (
      SELECT id FROM flash_events WHERE public = true AND status = 'published'
    )
  );

-- ============================================================
-- 6. generate_flash_event_slots(event_id)
--    Inserts open slots from event start_time → end_time at slot_duration_min
--    intervals on event_date. Skips slots that already exist (idempotent).
--    Must be called as studio member (service-role in webhook/action).
-- ============================================================

CREATE OR REPLACE FUNCTION generate_flash_event_slots(p_event_id uuid)
RETURNS int  -- returns number of slots generated
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event         flash_events%ROWTYPE;
  v_slot_start    timestamptz;
  v_slot_end      timestamptz;
  v_event_tz      text;
  v_base_date     date;
  v_current       timestamptz;
  v_count         int := 0;
BEGIN
  SELECT * INTO v_event FROM flash_events WHERE id = p_event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'flash_event not found: %', p_event_id;
  END IF;

  -- Resolve studio timezone
  SELECT timezone INTO v_event_tz FROM studios WHERE id = v_event.studio_id;
  v_event_tz := COALESCE(v_event_tz, 'UTC');

  v_base_date := v_event.event_date;

  -- Build start timestamp in studio local time, then convert to UTC
  v_current := (v_base_date::text || ' ' || v_event.start_time::text)::timestamptz AT TIME ZONE v_event_tz;

  LOOP
    v_slot_start := v_current;
    v_slot_end   := v_current + (v_event.slot_duration_min || ' minutes')::interval;

    -- Stop if slot_end exceeds end_time
    EXIT WHEN v_slot_end > (v_base_date::text || ' ' || v_event.end_time::text)::timestamptz AT TIME ZONE v_event_tz;

    -- Respect max_slots
    EXIT WHEN v_event.max_slots IS NOT NULL AND v_count >= v_event.max_slots;

    INSERT INTO flash_event_slots (flash_event_id, slot_start, slot_end, status)
    VALUES (p_event_id, v_slot_start, v_slot_end, 'open')
    ON CONFLICT (flash_event_id, slot_start) DO NOTHING;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_count := v_count + 1;  -- approximate; ON CONFLICT may not insert

    v_current := v_slot_end;
  END LOOP;

  -- Re-count actual slots
  SELECT COUNT(*) INTO v_count FROM flash_event_slots WHERE flash_event_id = p_event_id AND status = 'open';
  RETURN v_count;
END;
$$;

-- ============================================================
-- 7. public_reserve_flash_slot(studio_slug, event_slug, slot_id, client_info)
--    SECURITY DEFINER — called by anon public booking page.
--    Atomically claims a slot (open → reserved) and creates a pending booking row.
--    Returns: { booking_token, slot_id, error? }
-- ============================================================

CREATE OR REPLACE FUNCTION public_reserve_flash_slot(
  p_studio_slug  text,
  p_event_slug   text,
  p_slot_id      uuid,
  p_client_info  jsonb  -- { first_name, last_name?, email, phone?, notes? }
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_studio       studios%ROWTYPE;
  v_event        flash_events%ROWTYPE;
  v_slot         flash_event_slots%ROWTYPE;
  v_client_id    uuid;
  v_booking_id   uuid;
  v_booking_token text;
  v_artist_id    uuid;
BEGIN
  -- Resolve studio
  SELECT * INTO v_studio FROM studios WHERE slug = p_studio_slug AND status = 'active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'studio_not_found');
  END IF;

  -- Resolve event (must be public+published)
  SELECT * INTO v_event
  FROM flash_events
  WHERE studio_id = v_studio.id
    AND slug = p_event_slug
    AND public = true
    AND status = 'published';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'event_not_found');
  END IF;

  -- Lock and claim slot atomically
  SELECT * INTO v_slot
  FROM flash_event_slots
  WHERE id = p_slot_id
    AND flash_event_id = v_event.id
    AND status = 'open'
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    -- Either slot gone or already locked by concurrent request
    RETURN jsonb_build_object('error', 'slot_unavailable');
  END IF;

  -- Expire stale reservations opportunistically
  UPDATE flash_event_slots
  SET status = 'open', booking_id = NULL, reserved_until = NULL
  WHERE flash_event_id = v_event.id
    AND status = 'reserved'
    AND reserved_until < now();

  -- Upsert client by email within this studio
  INSERT INTO clients (studio_id, first_name, last_name, email, phone, source, created_at, updated_at)
  VALUES (
    v_studio.id,
    p_client_info->>'first_name',
    NULLIF(p_client_info->>'last_name', ''),
    LOWER(TRIM(p_client_info->>'email')),
    NULLIF(p_client_info->>'phone', ''),
    'public',
    now(),
    now()
  )
  ON CONFLICT (studio_id, email) DO UPDATE
    SET updated_at = now()
  RETURNING id INTO v_client_id;

  -- Resolve artist (use event artist if set, else use a placeholder approach)
  v_artist_id := v_event.artist_id;
  IF v_artist_id IS NULL THEN
    -- Pick the first active artist for this studio as a fallback
    SELECT id INTO v_artist_id FROM artists
    WHERE studio_id = v_studio.id AND status = 'active'
    ORDER BY sort_order LIMIT 1;
  END IF;

  IF v_artist_id IS NULL THEN
    RETURN jsonb_build_object('error', 'no_artist_available');
  END IF;

  -- Generate booking token
  v_booking_token := gen_random_uuid()::text;
  v_booking_id    := gen_random_uuid();

  -- Create pending booking
  INSERT INTO bookings (
    id, studio_id, client_id, artist_id,
    scheduled_at, duration_min,
    status, price_cents, deposit_cents, deposit_paid,
    booking_token, source,
    notes, client_notes,
    location_id, metadata,
    consent_required,
    created_at, updated_at
  ) VALUES (
    v_booking_id,
    v_studio.id,
    v_client_id,
    v_artist_id,
    v_slot.slot_start,
    v_event.slot_duration_min,
    'pending',
    v_event.slot_price_cents,
    v_event.deposit_cents,
    false,
    v_booking_token,
    'public',
    NULLIF(p_client_info->>'notes', ''),
    NULL,
    v_event.location_id,
    jsonb_build_object('flash_event_id', v_event.id, 'flash_event_slug', v_event.slug),
    false,
    now(),
    now()
  );

  -- Reserve the slot (15-minute hold)
  UPDATE flash_event_slots
  SET status         = 'reserved',
      booking_id     = v_booking_id,
      reserved_until = now() + interval '15 minutes'
  WHERE id = v_slot.id;

  RETURN jsonb_build_object(
    'booking_token', v_booking_token,
    'booking_id',    v_booking_id,
    'slot_id',       v_slot.id
  );
END;
$$;

-- ============================================================
-- 8. confirm_flash_slot_booking(booking_id)
--    Called by webhook after deposit paid. Transitions slot reserved → booked.
-- ============================================================

CREATE OR REPLACE FUNCTION confirm_flash_slot_booking(p_booking_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  UPDATE flash_event_slots
  SET status = 'booked', reserved_until = NULL
  WHERE booking_id = p_booking_id
    AND status IN ('open', 'reserved');

  RETURN FOUND;
END;
$$;

