import { createClient } from '@/lib/supabase/server'
import { createPublicClient } from '@/lib/supabase/public'
import { logger } from '@/lib/logger'
import type { FlashEvent, FlashEventDesign, FlashEventSlot } from '@/lib/supabase/types'

// ── Enriched types for list / detail views ───────────────────────────────────

export interface FlashEventListItem extends FlashEvent {
  artist: { id: string; display_name: string; avatar_url: string | null } | null
  location: { id: string; name: string } | null
  slot_summary: {
    total: number
    booked: number
    available: number
  }
}

export interface FlashEventDetail extends FlashEvent {
  artist: {
    id: string
    display_name: string
    avatar_url: string | null
    bio: string | null
    specialties: string[]
  } | null
  location: {
    id: string
    name: string
    address: string | null
    city: string | null
    state: string | null
  } | null
  designs: FlashEventDesign[]
  slot_summary: {
    total: number
    booked: number
    reserved: number
    available: number
  }
}

export interface FlashEventSlotWithBooking extends FlashEventSlot {
  booking: {
    id: string
    booking_token: string
    deposit_paid: boolean
    client: { id: string; first_name: string; last_name: string | null; email: string | null } | null
  } | null
}

export type FlashEventFilter = {
  status?: FlashEvent['status'] | 'upcoming' | 'all'
}

// ── List flash events for a studio ───────────────────────────────────────────

export async function listFlashEvents(
  studioId: string,
  filters: FlashEventFilter = {}
): Promise<FlashEventListItem[]> {
  const supabase = await createClient()

  let query = supabase
    .from('flash_events')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url),
      location:locations(id, name)
    `)
    .eq('studio_id', studioId)
    .order('event_date', { ascending: false })

  if (filters.status && filters.status !== 'all') {
    if (filters.status === 'upcoming') {
      const today = new Date().toISOString().split('T')[0]
      query = query.gte('event_date', today)
    } else {
      query = query.eq('status', filters.status)
    }
  }

  const { data, error } = await query

  if (error) {
    logger.error({ error, studioId }, 'listFlashEvents failed')
    throw new Error('Failed to load flash events')
  }

  if (!data) return []

  // Fetch slot summaries in bulk
  const eventIds = data.map((e) => e.id)
  const { data: slots } = await supabase
    .from('flash_event_slots')
    .select('flash_event_id, status')
    .in('flash_event_id', eventIds)

  const summaryMap = new Map<string, { total: number; booked: number; available: number }>()
  for (const slot of slots ?? []) {
    const existing = summaryMap.get(slot.flash_event_id) ?? { total: 0, booked: 0, available: 0 }
    existing.total += 1
    if (slot.status === 'booked') existing.booked += 1
    if (slot.status === 'open') existing.available += 1
    summaryMap.set(slot.flash_event_id, existing)
  }

  return data.map((event) => ({
    ...event,
    artist: (event.artist as FlashEventListItem['artist']) ?? null,
    location: (event.location as FlashEventListItem['location']) ?? null,
    slot_summary: summaryMap.get(event.id) ?? { total: 0, booked: 0, available: 0 },
  }))
}

// ── Get single flash event with full details (authenticated) ─────────────────

export async function getFlashEvent(
  studioId: string,
  eventId: string
): Promise<FlashEventDetail | null> {
  const supabase = await createClient()

  const { data: event, error } = await supabase
    .from('flash_events')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url, bio, specialties),
      location:locations(id, name, address, city, state)
    `)
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (error) {
    logger.error({ error, studioId, eventId }, 'getFlashEvent failed')
    throw new Error('Failed to load flash event')
  }
  if (!event) return null

  const { data: designs } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq('flash_event_id', eventId)
    .order('display_order', { ascending: true })

  const { data: slots } = await supabase
    .from('flash_event_slots')
    .select('status')
    .eq('flash_event_id', eventId)

  const slotCounts = (slots ?? []).reduce(
    (acc, s) => {
      acc.total += 1
      if (s.status === 'booked') acc.booked += 1
      if (s.status === 'reserved') acc.reserved += 1
      if (s.status === 'open') acc.available += 1
      return acc
    },
    { total: 0, booked: 0, reserved: 0, available: 0 }
  )

  return {
    ...event,
    artist: (event.artist as FlashEventDetail['artist']) ?? null,
    location: (event.location as FlashEventDetail['location']) ?? null,
    designs: designs ?? [],
    slot_summary: slotCounts,
  }
}

// ── Get flash event by studio slug + event slug (PUBLIC, anon) ────────────────

export async function getFlashEventBySlug(
  studioSlug: string,
  eventSlug: string
): Promise<FlashEventDetail | null> {
  const supabase = createPublicClient()

  // Resolve studio first
  const { data: studio } = await supabase
    .from('studios')
    .select('id')
    .eq('slug', studioSlug)
    .maybeSingle()

  if (!studio) return null

  const { data: event, error } = await supabase
    .from('flash_events')
    .select(`
      *,
      artist:artists(id, display_name, avatar_url, bio, specialties),
      location:locations(id, name, address, city, state)
    `)
    .eq('studio_id', studio.id)
    .eq('slug', eventSlug)
    .eq('public', true)
    .eq('status', 'published')
    .maybeSingle()

  if (error) {
    logger.error({ error, studioSlug, eventSlug }, 'getFlashEventBySlug failed')
    return null
  }
  if (!event) return null

  const { data: designs } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq('flash_event_id', event.id)
    .order('display_order', { ascending: true })

  const { data: slots } = await supabase
    .from('flash_event_slots')
    .select('status')
    .eq('flash_event_id', event.id)

  const slotCounts = (slots ?? []).reduce(
    (acc, s) => {
      acc.total += 1
      if (s.status === 'booked') acc.booked += 1
      if (s.status === 'reserved') acc.reserved += 1
      if (s.status === 'open') acc.available += 1
      return acc
    },
    { total: 0, booked: 0, reserved: 0, available: 0 }
  )

  return {
    ...event,
    artist: (event.artist as FlashEventDetail['artist']) ?? null,
    location: (event.location as FlashEventDetail['location']) ?? null,
    designs: designs ?? [],
    slot_summary: slotCounts,
  }
}

// ── Get all slots for an event (authenticated, with booking info) ─────────────

export async function getFlashEventSlots(
  studioId: string,
  eventId: string,
  options: { available?: boolean } = {}
): Promise<FlashEventSlotWithBooking[]> {
  const supabase = await createClient()

  // Verify ownership
  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  let query = supabase
    .from('flash_event_slots')
    .select(`
      *,
      booking:bookings(id, booking_token, deposit_paid,
        client:clients(id, first_name, last_name, email)
      )
    `)
    .eq('flash_event_id', eventId)
    .order('slot_start', { ascending: true })

  if (options.available) {
    query = query.eq('status', 'open')
  }

  const { data, error } = await query

  if (error) {
    logger.error({ error, studioId, eventId }, 'getFlashEventSlots failed')
    throw new Error('Failed to load slots')
  }

  return (data ?? []) as FlashEventSlotWithBooking[]
}

// ── Get all slots for public booking page (anon) ──────────────────────────────

export async function getPublicFlashEventSlots(eventId: string): Promise<FlashEventSlot[]> {
  const supabase = createPublicClient()

  const { data, error } = await supabase
    .from('flash_event_slots')
    .select('id, flash_event_id, slot_start, slot_end, status, design_id, reserved_until, created_at, booking_id')
    .eq('flash_event_id', eventId)
    .order('slot_start', { ascending: true })

  if (error) {
    logger.error({ error, eventId }, 'getPublicFlashEventSlots failed')
    return []
  }

  return data ?? []
}

// ── Get designs for an event (authenticated) ─────────────────────────────────

export async function getFlashEventDesigns(
  studioId: string,
  eventId: string
): Promise<FlashEventDesign[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq(
      'flash_event_id',
      supabase
        .from('flash_events')
        .select('id')
        .eq('studio_id', studioId)
        .eq('id', eventId)
    )
    .order('display_order', { ascending: true })

  // Simpler approach: verify ownership then query designs
  const { data: ownerCheck } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!ownerCheck) throw new Error('Event not found or access denied')

  const { data: designs, error: designsError } = await supabase
    .from('flash_event_designs')
    .select('*')
    .eq('flash_event_id', eventId)
    .order('display_order', { ascending: true })

  if (designsError) {
    logger.error({ error: designsError, studioId, eventId }, 'getFlashEventDesigns failed')
    throw new Error('Failed to load designs')
  }

  // Suppress unused variable warning from first unused query
  void data
  void error

  return designs ?? []
}

import { createClient } from '@/lib/supabase/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { createPublicClient } from '@/lib/supabase/public'
import { logger } from '@/lib/logger'
import { slugify } from '@/lib/utils'
import type { FlashEvent, FlashEventDesign, FlashEventSlot } from '@/lib/supabase/types'
import type {
  FlashEventCreateInput,
  FlashEventUpdateInput,
  FlashDesignCreateInput,
  FlashDesignUpdateInput,
} from './schemas'

// ── Create a new flash event (status=draft) ───────────────────────────────────

export async function createFlashEvent(
  studioId: string,
  input: FlashEventCreateInput
): Promise<FlashEvent> {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  const slug = input.slug || slugify(input.title)

  const { data, error } = await supabase
    .from('flash_events')
    .insert({
      studio_id: studioId,
      artist_id: input.artistId ?? null,
      title: input.title,
      slug,
      description: input.description ?? null,
      event_date: input.eventDate,
      start_time: input.startTime,
      end_time: input.endTime,
      slot_duration_min: input.slotDurationMin,
      slot_price_cents: input.slotPriceCents ?? 0,
      deposit_cents: input.depositCents ?? 0,
      currency: input.currency ?? 'USD',
      max_slots: input.maxSlots ?? null,
      cover_image_url: input.coverImageUrl ?? null,
      flyer_url: input.flyerUrl ?? null,
      location_id: input.locationId ?? null,
      public: input.public ?? true,
      status: 'draft',
      created_by: user?.id ?? null,
    })
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId }, 'createFlashEvent failed')
    if (error.code === '23505') {
      throw new Error('An event with this slug already exists. Choose a different title or slug.')
    }
    throw new Error('Failed to create flash event')
  }

  return data
}

// ── Update a flash event ──────────────────────────────────────────────────────

export async function updateFlashEvent(
  studioId: string,
  eventId: string,
  input: FlashEventUpdateInput
): Promise<FlashEvent> {
  const supabase = await createClient()

  const updatePayload: Record<string, unknown> = {}
  if (input.title !== undefined) updatePayload.title = input.title
  if (input.slug !== undefined) updatePayload.slug = input.slug
  if (input.description !== undefined) updatePayload.description = input.description
  if (input.eventDate !== undefined) updatePayload.event_date = input.eventDate
  if (input.startTime !== undefined) updatePayload.start_time = input.startTime
  if (input.endTime !== undefined) updatePayload.end_time = input.endTime
  if (input.slotDurationMin !== undefined) updatePayload.slot_duration_min = input.slotDurationMin
  if (input.slotPriceCents !== undefined) updatePayload.slot_price_cents = input.slotPriceCents
  if (input.depositCents !== undefined) updatePayload.deposit_cents = input.depositCents
  if (input.currency !== undefined) updatePayload.currency = input.currency
  if (input.maxSlots !== undefined) updatePayload.max_slots = input.maxSlots
  if (input.coverImageUrl !== undefined) updatePayload.cover_image_url = input.coverImageUrl
  if (input.flyerUrl !== undefined) updatePayload.flyer_url = input.flyerUrl
  if (input.locationId !== undefined) updatePayload.location_id = input.locationId
  if (input.artistId !== undefined) updatePayload.artist_id = input.artistId
  if (input.public !== undefined) updatePayload.public = input.public

  const { data, error } = await supabase
    .from('flash_events')
    .update(updatePayload)
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, eventId }, 'updateFlashEvent failed')
    if (error.code === '23505') {
      throw new Error('A slug conflict occurred. Choose a different slug.')
    }
    throw new Error('Failed to update flash event')
  }

  return data
}

// ── Publish a flash event (draft → published + generates slots) ───────────────

export async function publishFlashEvent(
  studioId: string,
  eventId: string
): Promise<{ event: FlashEvent; slotsGenerated: number }> {
  // Service-role needed to call SECURITY DEFINER RPC
  const supabase = createServiceRoleClient()

  // Verify ownership (re-check with user client)
  const userClient = await createClient()
  const { data: event } = await userClient
    .from('flash_events')
    .select('*')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .eq('status', 'draft')
    .maybeSingle()

  if (!event) throw new Error('Event not found, already published, or access denied')

  // Generate slots via RPC
  const { data: slotsGenerated, error: rpcError } = await supabase.rpc(
    'generate_flash_event_slots',
    { p_event_id: eventId }
  )

  if (rpcError) {
    logger.error({ error: rpcError, studioId, eventId }, 'generate_flash_event_slots RPC failed')
    throw new Error('Failed to generate time slots')
  }

  // Transition to published
  const { data: published, error: updateError } = await supabase
    .from('flash_events')
    .update({ status: 'published', published_at: new Date().toISOString() })
    .eq('id', eventId)
    .select()
    .single()

  if (updateError) {
    logger.error({ error: updateError, studioId, eventId }, 'publishFlashEvent status update failed')
    throw new Error('Failed to publish event')
  }

  return { event: published, slotsGenerated: slotsGenerated ?? 0 }
}

// ── Cancel a flash event ──────────────────────────────────────────────────────

export async function cancelFlashEvent(studioId: string, eventId: string): Promise<FlashEvent> {
  const supabase = await createClient()

  // Cancel all open/reserved slots
  await supabase
    .from('flash_event_slots')
    .update({ status: 'blocked' })
    .eq('flash_event_id', eventId)
    .in('status', ['open', 'reserved'])

  const { data, error } = await supabase
    .from('flash_events')
    .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, eventId }, 'cancelFlashEvent failed')
    throw new Error('Failed to cancel event')
  }

  return data
}

// ── Design management ─────────────────────────────────────────────────────────

export async function addDesign(
  studioId: string,
  eventId: string,
  input: FlashDesignCreateInput
): Promise<FlashEventDesign> {
  const supabase = await createClient()

  // Verify ownership
  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  const { data, error } = await supabase
    .from('flash_event_designs')
    .insert({
      flash_event_id: eventId,
      title: input.title,
      image_url: input.imageUrl,
      size_description: input.sizeDescription ?? null,
      placement_options: input.placementOptions ?? null,
      price_cents: input.priceCents ?? null,
      display_order: input.displayOrder ?? 0,
    })
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, eventId }, 'addDesign failed')
    throw new Error('Failed to add design')
  }

  return data
}

export async function updateDesign(
  studioId: string,
  eventId: string,
  designId: string,
  input: FlashDesignUpdateInput
): Promise<FlashEventDesign> {
  const supabase = await createClient()

  // Verify ownership via flash_events
  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  const updatePayload: Record<string, unknown> = {}
  if (input.title !== undefined) updatePayload.title = input.title
  if (input.imageUrl !== undefined) updatePayload.image_url = input.imageUrl
  if (input.sizeDescription !== undefined) updatePayload.size_description = input.sizeDescription
  if (input.placementOptions !== undefined) updatePayload.placement_options = input.placementOptions
  if (input.priceCents !== undefined) updatePayload.price_cents = input.priceCents
  if (input.displayOrder !== undefined) updatePayload.display_order = input.displayOrder
  if (input.soldOut !== undefined) updatePayload.sold_out = input.soldOut

  const { data, error } = await supabase
    .from('flash_event_designs')
    .update(updatePayload)
    .eq('id', designId)
    .eq('flash_event_id', eventId)
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, eventId, designId }, 'updateDesign failed')
    throw new Error('Failed to update design')
  }

  return data
}

export async function removeDesign(
  studioId: string,
  eventId: string,
  designId: string
): Promise<void> {
  const supabase = await createClient()

  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  const { error } = await supabase
    .from('flash_event_designs')
    .delete()
    .eq('id', designId)
    .eq('flash_event_id', eventId)

  if (error) {
    logger.error({ error, studioId, eventId, designId }, 'removeDesign failed')
    throw new Error('Failed to remove design')
  }
}

export async function reorderDesigns(
  studioId: string,
  eventId: string,
  orderedIds: string[]
): Promise<void> {
  const supabase = await createClient()

  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  // Batch update display_order
  await Promise.all(
    orderedIds.map((id, index) =>
      supabase
        .from('flash_event_designs')
        .update({ display_order: index })
        .eq('id', id)
        .eq('flash_event_id', eventId)
    )
  )
}

// ── Slot management ───────────────────────────────────────────────────────────

export async function blockSlot(
  studioId: string,
  eventId: string,
  slotId: string
): Promise<FlashEventSlot> {
  const supabase = await createClient()

  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  const { data, error } = await supabase
    .from('flash_event_slots')
    .update({ status: 'blocked' })
    .eq('id', slotId)
    .eq('flash_event_id', eventId)
    .in('status', ['open'])
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, slotId }, 'blockSlot failed')
    throw new Error('Failed to block slot')
  }

  return data
}

export async function unblockSlot(
  studioId: string,
  eventId: string,
  slotId: string
): Promise<FlashEventSlot> {
  const supabase = await createClient()

  const { data: event } = await supabase
    .from('flash_events')
    .select('id')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (!event) throw new Error('Event not found or access denied')

  const { data, error } = await supabase
    .from('flash_event_slots')
    .update({ status: 'open' })
    .eq('id', slotId)
    .eq('flash_event_id', eventId)
    .eq('status', 'blocked')
    .select()
    .single()

  if (error) {
    logger.error({ error, studioId, slotId }, 'unblockSlot failed')
    throw new Error('Failed to unblock slot')
  }

  return data
}

// ── Public: reserve a slot (anon, 15-min hold) ────────────────────────────────

export type ReserveSlotResult =
  | { success: true; bookingToken: string; bookingId: string; slotId: string }
  | { success: false; error: string }

export async function reserveSlot(
  studioSlug: string,
  eventSlug: string,
  slotId: string,
  clientInfo: {
    firstName: string
    lastName?: string
    email: string
    phone?: string
    notes?: string
  }
): Promise<ReserveSlotResult> {
  const supabase = createPublicClient()

  const { data, error } = await supabase.rpc('public_reserve_flash_slot', {
    p_studio_slug: studioSlug,
    p_event_slug: eventSlug,
    p_slot_id: slotId,
    p_client_info: {
      first_name: clientInfo.firstName,
      last_name: clientInfo.lastName ?? null,
      email: clientInfo.email,
      phone: clientInfo.phone ?? null,
      notes: clientInfo.notes ?? null,
    },
  })

  if (error) {
    logger.error({ error, studioSlug, eventSlug, slotId }, 'reserveSlot RPC failed')
    return { success: false, error: 'Unable to reserve slot. Please try again.' }
  }

  const result = data as Record<string, unknown>
  if (result?.error) {
    const errMap: Record<string, string> = {
      studio_not_found: 'Studio not found.',
      event_not_found: 'Event not found or no longer available.',
      slot_unavailable: 'That slot is no longer available. Please choose another.',
      no_artist_available: 'No artists are available for this event.',
    }
    return {
      success: false,
      error: errMap[result.error as string] ?? 'Unable to complete reservation.',
    }
  }

  return {
    success: true,
    bookingToken: result.booking_token as string,
    bookingId: result.booking_id as string,
    slotId: result.slot_id as string,
  }
}

// ── Confirm slot after deposit paid (called by webhook) ───────────────────────

export async function confirmSlotBooking(bookingId: string): Promise<boolean> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase.rpc('confirm_flash_slot_booking', {
    p_booking_id: bookingId,
  })

  if (error) {
    logger.error({ error, bookingId }, 'confirmSlotBooking RPC failed')
    return false
  }

  return data === true
}

