'use server'

import { redirect } from 'next/navigation'
import { revalidatePath } from 'next/cache'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import {
  createFlashEvent,
  updateFlashEvent,
  publishFlashEvent,
  cancelFlashEvent,
  addDesign,
  updateDesign,
  removeDesign,
  reorderDesigns,
  blockSlot,
  unblockSlot,
} from '@/lib/flash-events/mutations'
import {
  flashEventCreateSchema,
  flashEventUpdateSchema,
  flashDesignCreateSchema,
  flashDesignUpdateSchema,
} from '@/lib/flash-events/schemas'
import { logger } from '@/lib/logger'

type ActionResult = { success: boolean; error?: string }

// ── Create ────────────────────────────────────────────────────────────────────

export async function createFlashEventAction(
  formData: FormData
): Promise<ActionResult & { id?: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  const raw = {
    title: formData.get('title'),
    slug: formData.get('slug') || undefined,
    description: formData.get('description') || undefined,
    eventDate: formData.get('eventDate'),
    startTime: formData.get('startTime'),
    endTime: formData.get('endTime'),
    slotDurationMin: Number(formData.get('slotDurationMin')),
    slotPriceCents: Number(formData.get('slotPriceCents') ?? 0),
    depositCents: Number(formData.get('depositCents') ?? 0),
    currency: formData.get('currency') || 'USD',
    maxSlots: formData.get('maxSlots') ? Number(formData.get('maxSlots')) : undefined,
    coverImageUrl: formData.get('coverImageUrl') || undefined,
    flyerUrl: formData.get('flyerUrl') || undefined,
    locationId: formData.get('locationId') || undefined,
    artistId: formData.get('artistId') || undefined,
    public: formData.get('public') !== 'false',
  }

  const parsed = flashEventCreateSchema.safeParse(raw)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
  }

  try {
    const event = await createFlashEvent(auth.studioId, parsed.data)
    revalidatePath('/flash-events')
    return { success: true, id: event.id }
  } catch (err) {
    logger.error({ err }, 'createFlashEventAction failed')
    const message = err instanceof Error ? err.message : 'Failed to create event'
    return { success: false, error: message }
  }
}

// ── Update ────────────────────────────────────────────────────────────────────

export async function updateFlashEventAction(
  eventId: string,
  formData: FormData
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  const raw: Record<string, unknown> = {}
  const title = formData.get('title')
  if (title) raw.title = title
  const slug = formData.get('slug')
  if (slug) raw.slug = slug
  const description = formData.get('description')
  if (description !== null) raw.description = description || null
  const eventDate = formData.get('eventDate')
  if (eventDate) raw.eventDate = eventDate
  const startTime = formData.get('startTime')
  if (startTime) raw.startTime = startTime
  const endTime = formData.get('endTime')
  if (endTime) raw.endTime = endTime
  const slotDurationMin = formData.get('slotDurationMin')
  if (slotDurationMin) raw.slotDurationMin = Number(slotDurationMin)
  const slotPriceCents = formData.get('slotPriceCents')
  if (slotPriceCents !== null) raw.slotPriceCents = Number(slotPriceCents)
  const depositCents = formData.get('depositCents')
  if (depositCents !== null) raw.depositCents = Number(depositCents)
  const maxSlots = formData.get('maxSlots')
  if (maxSlots !== null) raw.maxSlots = maxSlots ? Number(maxSlots) : null
  const coverImageUrl = formData.get('coverImageUrl')
  if (coverImageUrl !== null) raw.coverImageUrl = coverImageUrl || null
  const flyerUrl = formData.get('flyerUrl')
  if (flyerUrl !== null) raw.flyerUrl = flyerUrl || null
  const locationId = formData.get('locationId')
  if (locationId !== null) raw.locationId = locationId || null
  const artistId = formData.get('artistId')
  if (artistId !== null) raw.artistId = artistId || null
  const isPublic = formData.get('public')
  if (isPublic !== null) raw.public = isPublic !== 'false'

  const parsed = flashEventUpdateSchema.safeParse(raw)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
  }

  try {
    await updateFlashEvent(auth.studioId, eventId, parsed.data)
    revalidatePath(`/flash-events/${eventId}`)
    revalidatePath('/flash-events')
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId }, 'updateFlashEventAction failed')
    const message = err instanceof Error ? err.message : 'Failed to update event'
    return { success: false, error: message }
  }
}

// ── Publish ───────────────────────────────────────────────────────────────────

export async function publishFlashEventAction(eventId: string): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin'].includes(auth.role)) {
    return { success: false, error: 'Only owners and admins can publish events' }
  }

  try {
    const { slotsGenerated } = await publishFlashEvent(auth.studioId, eventId)
    revalidatePath(`/flash-events/${eventId}`)
    revalidatePath('/flash-events')
    logger.info({ eventId, slotsGenerated }, 'Flash event published')
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId }, 'publishFlashEventAction failed')
    const message = err instanceof Error ? err.message : 'Failed to publish event'
    return { success: false, error: message }
  }
}

// ── Cancel ────────────────────────────────────────────────────────────────────

export async function cancelFlashEventAction(eventId: string): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin'].includes(auth.role)) {
    return { success: false, error: 'Only owners and admins can cancel events' }
  }

  try {
    await cancelFlashEvent(auth.studioId, eventId)
    revalidatePath(`/flash-events/${eventId}`)
    revalidatePath('/flash-events')
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId }, 'cancelFlashEventAction failed')
    const message = err instanceof Error ? err.message : 'Failed to cancel event'
    return { success: false, error: message }
  }
}

// ── Designs ───────────────────────────────────────────────────────────────────

export async function addDesignAction(
  eventId: string,
  formData: FormData
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }

  const raw = {
    title: formData.get('title'),
    imageUrl: formData.get('imageUrl'),
    sizeDescription: formData.get('sizeDescription') || undefined,
    placementOptions: formData.get('placementOptions') || undefined,
    priceCents: formData.get('priceCents') ? Number(formData.get('priceCents')) : undefined,
    displayOrder: formData.get('displayOrder') ? Number(formData.get('displayOrder')) : 0,
  }

  const parsed = flashDesignCreateSchema.safeParse(raw)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
  }

  try {
    await addDesign(auth.studioId, eventId, parsed.data)
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId }, 'addDesignAction failed')
    return { success: false, error: 'Failed to add design' }
  }
}

export async function updateDesignAction(
  eventId: string,
  designId: string,
  updates: Record<string, unknown>
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }

  const parsed = flashDesignUpdateSchema.safeParse(updates)
  if (!parsed.success) {
    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
  }

  try {
    await updateDesign(auth.studioId, eventId, designId, parsed.data)
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId, designId }, 'updateDesignAction failed')
    return { success: false, error: 'Failed to update design' }
  }
}

export async function removeDesignAction(
  eventId: string,
  designId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }

  try {
    await removeDesign(auth.studioId, eventId, designId)
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId, designId }, 'removeDesignAction failed')
    return { success: false, error: 'Failed to remove design' }
  }
}

export async function reorderDesignsAction(
  eventId: string,
  orderedIds: string[]
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }

  try {
    await reorderDesigns(auth.studioId, eventId, orderedIds)
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId }, 'reorderDesignsAction failed')
    return { success: false, error: 'Failed to reorder designs' }
  }
}

// ── Slots ─────────────────────────────────────────────────────────────────────

export async function blockSlotAction(
  eventId: string,
  slotId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }

  try {
    await blockSlot(auth.studioId, eventId, slotId)
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId, slotId }, 'blockSlotAction failed')
    return { success: false, error: 'Failed to block slot' }
  }
}

export async function unblockSlotAction(
  eventId: string,
  slotId: string
): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }

  try {
    await unblockSlot(auth.studioId, eventId, slotId)
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true }
  } catch (err) {
    logger.error({ err, eventId, slotId }, 'unblockSlotAction failed')
    return { success: false, error: 'Failed to unblock slot' }
  }
}

// ── Delete (redirect after) ───────────────────────────────────────────────────

export async function deleteFlashEventAction(eventId: string): Promise<void> {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')
  if (!['owner', 'admin'].includes(auth.role)) redirect(`/flash-events/${eventId}`)

  // Cancel first (frees slots), then delete
  try {
    await cancelFlashEvent(auth.studioId, eventId)
  } catch {
    // Best-effort
  }

  const { createClient } = await import('@/lib/supabase/server')
  const supabase = await createClient()
  await supabase
    .from('flash_events')
    .delete()
    .eq('id', eventId)
    .eq('studio_id', auth.studioId)

  revalidatePath('/flash-events')
  redirect('/flash-events')
}

