  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import {
  Zap, Settings, ImageIcon, CalendarDays, BarChart2,
  ArrowLeft, ExternalLink, Loader2, Check, X, Lock, Unlock, Globe
} from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import type { FlashEventDetail, FlashEventSlotWithBooking } from '@/lib/flash-events/queries'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import {
  publishFlashEventAction,
  cancelFlashEventAction,
  removeDesignAction,
  reorderDesignsAction,
  blockSlotAction,
  unblockSlotAction,
} from '@/app/(app)/flash-events/actions'
import { FlashEventDesignsTab } from './FlashEventDesignsTab'
import { FlashEventSlotsTab } from './FlashEventSlotsTab'

const STATUS_CONFIG: Record<string, { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }> = {
  draft: { label: 'Draft', variant: 'secondary' },
  published: { label: 'Published', variant: 'default' },
  completed: { label: 'Completed', variant: 'outline' },
  cancelled: { label: 'Cancelled', variant: 'destructive' },
}

const TABS = [
  { id: 'overview', label: 'Overview', icon: BarChart2 },
  { id: 'designs', label: 'Designs', icon: ImageIcon },
  { id: 'slots', label: 'Slots', icon: CalendarDays },
  { id: 'settings', label: 'Settings', icon: Settings },
] as const

type TabId = (typeof TABS)[number]['id']

interface Props {
  event: FlashEventDetail
  slots: FlashEventSlotWithBooking[]
  role: NavRole
  initialTab: string
  studioId: string
}

export function FlashEventDetailShell({ event, slots, role, initialTab, studioId }: Props) {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState<TabId>(
    TABS.find((t) => t.id === initialTab)?.id ?? 'overview'
  )
  const [isPending, startTransition] = useTransition()

  const canManage = ['owner', 'admin'].includes(role)
  const canEdit = ['owner', 'admin', 'receptionist'].includes(role)

  const eventDateFormatted = new Date(event.event_date + 'T00:00:00').toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  })

  function handlePublish() {
    startTransition(async () => {
      const result = await publishFlashEventAction(event.id)
      if (result.success) {
        toast.success('Event published — slots generated')
        router.refresh()
      } else {
        toast.error(result.error ?? 'Failed to publish')
      }
    })
  }

  function handleCancel() {
    startTransition(async () => {
      const result = await cancelFlashEventAction(event.id)
      if (result.success) {
        toast.success('Event cancelled')
        router.refresh()
      } else {
        toast.error(result.error ?? 'Failed to cancel')
      }
    })
  }

  const statusCfg = STATUS_CONFIG[event.status] ?? STATUS_CONFIG.draft
  const publicUrl = `/book/${studioId}/flash/${event.slug}`

  return (
    <div className="space-y-0">
      {/* Page header */}
      <div className="border-b border-border/40 bg-card/50">
        <div className="px-6 py-4 space-y-3">
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="icon" className="h-7 w-7" asChild>
              <Link href="/flash-events">
                <ArrowLeft className="h-4 w-4" />
              </Link>
            </Button>
            <div className="flex items-center gap-2 min-w-0 flex-1">
              <Zap className="h-4 w-4 text-primary shrink-0" />
              <h1 className="text-base font-semibold truncate">{event.title}</h1>
              <Badge variant={statusCfg.variant} className="text-[10px] shrink-0">
                {statusCfg.label}
              </Badge>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            {canEdit && event.status !== 'cancelled' && event.status !== 'completed' && (
              <Button variant="outline" size="sm" asChild>
                <Link href={`/flash-events/${event.id}/edit`}>
                  <Settings className="h-3.5 w-3.5 mr-1.5" />
                  Edit
                </Link>
              </Button>
            )}
            {canManage && event.status === 'draft' && (
              <Button size="sm" onClick={handlePublish} disabled={isPending}>
                {isPending ? (
                  <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                ) : (
                  <Globe className="h-3.5 w-3.5 mr-1.5" />
                )}
                Publish
              </Button>
            )}
            {event.status === 'published' && (
              <Button variant="outline" size="sm" asChild>
                <Link href={publicUrl} target="_blank">
                  <ExternalLink className="h-3.5 w-3.5 mr-1.5" />
                  View public page
                </Link>
