      <div className="p-6">
        {activeTab === 'overview' && (
          <OverviewTab event={event} />
        )}
        {activeTab === 'designs' && (
          <FlashEventDesignsTab
            event={event}
            canEdit={canEdit}
            onRemove={async (designId) => {
              const result = await removeDesignAction(event.id, designId)
              if (result.success) {
