          <InfoRow label="Hours" value={`${event.start_time.slice(0, 5)} – ${event.end_time.slice(0, 5)}`} />
          <InfoRow label="Slot duration" value={`${event.slot_duration_min} minutes`} />
          {event.artist && <InfoRow label="Artist" value={event.artist.display_name} />}
          {event.location && <InfoRow label="Location" value={event.location.name} />}
          {event.slot_price_cents > 0 && (
            <InfoRow label="Slot price" value={formatCurrency(event.slot_price_cents)} />
