    <div className="rounded-lg border border-border/60 bg-card p-3 space-y-0.5">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className={cn('text-2xl font-bold tabular-nums', highlight && 'text-primary')}>
        {value}
      </p>
