function InfoRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="flex justify-between gap-4">
      <span className="text-muted-foreground shrink-0">{label}</span>
      <span className="text-right font-medium">{value}</span>
    </div>
  )
}

// ── Settings tab ─────────────────────────────────────────────────────────────

function SettingsTab({ canEdit, eventId }: { event: FlashEventDetail; canEdit: boolean; eventId: string }) {
  return (
    <div className="max-w-md space-y-4">
      <p className="text-sm text-muted-foreground">
        Edit event settings including title, timing, pricing, and artist.
      </p>
      {canEdit ? (
        <Button asChild>
          <Link href={`/flash-events/${eventId}/edit`}>
            <Settings className="h-4 w-4 mr-2" />
            Open settings editor
          </Link>
        </Button>
      ) : (
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Lock className="h-4 w-4" />
          You need admin permissions to edit this event.
        </div>
      )}
    </div>
  )
}

'use client'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Lock, Unlock, Check, Clock } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { FlashEventDetail, FlashEventSlotWithBooking } from '@/lib/flash-events/queries'

const STATUS_CONFIG: Record<
  string,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline'; dot: string }
> = {
  open: { label: 'Open', variant: 'outline', dot: 'bg-primary' },
  reserved: { label: 'Reserved', variant: 'secondary', dot: 'bg-warning' },
  booked: { label: 'Booked', variant: 'default', dot: 'bg-primary' },
  blocked: { label: 'Blocked', variant: 'destructive', dot: 'bg-destructive' },
}

interface Props {
  event: FlashEventDetail
  slots: FlashEventSlotWithBooking[]
  canManage: boolean
  onBlock: (slotId: string) => void
  onUnblock: (slotId: string) => void
}

export function FlashEventSlotsTab({ event, slots, canManage, onBlock, onUnblock }: Props) {
  if (event.status === 'draft') {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center space-y-3">
        <div className="h-12 w-12 rounded-xl bg-muted flex items-center justify-center">
          <Clock className="h-6 w-6 text-muted-foreground" />
        </div>
        <div className="space-y-1">
          <p className="text-sm font-medium">Slots not yet generated</p>
          <p className="text-xs text-muted-foreground max-w-xs">
            Publish this event to auto-generate time slots from{' '}
            {event.start_time.slice(0, 5)} to {event.end_time.slice(0, 5)}.
          </p>
        </div>
      </div>
    )
  }

  if (slots.length === 0) {
    return (
      <p className="text-sm text-muted-foreground py-8 text-center">
        No slots found for this event.
      </p>
    )
  }

  return (
    <div className="space-y-3 max-w-2xl">
      <p className="text-xs text-muted-foreground">
        {slots.length} slot{slots.length !== 1 ? 's' : ''} — click a slot to manage it
      </p>
      <div className="rounded-lg border border-border/60 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-28">Time</TableHead>
              <TableHead>Client</TableHead>
              <TableHead className="w-24">Deposit</TableHead>
              <TableHead className="w-24">Status</TableHead>
              {canManage && <TableHead className="w-20 text-right">Actions</TableHead>}
            </TableRow>
          </TableHeader>
          <TableBody>
            {slots.map((slot) => {
              const cfg = STATUS_CONFIG[slot.status] ?? STATUS_CONFIG.open
              const time = new Date(slot.slot_start).toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
              })
              const booking = slot.booking
              const client = booking?.client

              return (
                <TableRow key={slot.id} className={cn(slot.status === 'blocked' && 'opacity-50')}>
                  <TableCell className="font-mono text-xs tabular-nums">{time}</TableCell>
                  <TableCell className="text-sm">
                    {client ? (
                      <span>
                        {client.first_name} {client.last_name ?? ''}{' '}
                        {client.email && (
                          <span className="text-xs text-muted-foreground">— {client.email}</span>
                        )}
                      </span>
                    ) : (
                      <span className="text-muted-foreground text-xs">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {booking ? (
                      booking.deposit_paid ? (
                        <span className="flex items-center gap-1 text-xs text-primary">
                          <Check className="h-3 w-3" /> Paid
                        </span>
                      ) : (
                        <span className="text-xs text-warning">Unpaid</span>
                      )
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span className="flex items-center gap-1.5">
                      <span className={cn('h-1.5 w-1.5 rounded-full', cfg.dot)} />
                      <Badge variant={cfg.variant} className="text-[10px] px-1.5">
                        {cfg.label}
                      </Badge>
                    </span>
                  </TableCell>
                  {canManage && (
                    <TableCell className="text-right">
                      {slot.status === 'open' && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => onBlock(slot.id)}
                          title="Block slot"
                        >
                          <Lock className="h-3 w-3" />
                        </Button>
                      )}
                      {slot.status === 'blocked' && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-6 w-6"
                          onClick={() => onUnblock(slot.id)}
                          title="Unblock slot"
                        >
                          <Unlock className="h-3 w-3" />
                        </Button>
                      )}
                    </TableCell>
                  )}
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

