'use client'

import { use, useState, useCallback, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { toast } from 'sonner'
import { Typography } from '@/components/ui/typography'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { TrustBadges } from '@/components/booking/TrustBadges'
import { CalendarDays, Clock, MapPin, ChevronLeft, Check, Loader2, User } from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import { z } from 'zod'

// ── Types ────────────────────────────────────────────────────────────────────

interface StudioPublic {
  id: string
  name: string
  slug: string
  brand_color: string | null
  logo_url: string | null
}

interface DesignPublic {
  id: string
  title: string
  image_url: string
  size_description: string | null
  placement_options: string | null
  price_cents: number | null
  display_order: number
  sold_out: boolean
}

interface SlotPublic {
  id: string
  slot_start: string
  slot_end: string
  status: 'open' | 'reserved' | 'booked' | 'blocked'
}

interface EventPublic {
  id: string
  title: string
  description: string | null
  event_date: string
  start_time: string
  end_time: string
  slot_duration_min: number
  slot_price_cents: number
  deposit_cents: number
  cover_image_url: string | null
  public: boolean
  status: string
  artist: { display_name: string; avatar_url: string | null; bio: string | null } | null
  location: { name: string; address: string | null; city: string | null; state: string | null } | null
  designs: DesignPublic[]
}

// ── Form schema ──────────────────────────────────────────────────────────────

const ClientSchema = z.object({
  firstName: z.string().min(1, 'First name is required').max(100),
  lastName: z.string().max(100).optional(),
  email: z.string().email('Enter a valid email').max(254),
  phone: z.string().max(30).optional(),
  notes: z.string().max(2000).optional(),
})
type ClientForm = z.infer<typeof ClientSchema>

// ── Page ─────────────────────────────────────────────────────────────────────

export default function PublicFlashEventPage({
  params,
}: {
  params: Promise<{ studioSlug: string; eventSlug: string }>
}) {
  const { studioSlug, eventSlug } = use(params)
  const router = useRouter()

  const [selectedDesignId, setSelectedDesignId] = useState<string | null>(null)
  const [selectedSlotId, setSelectedSlotId] = useState<string | null>(null)
  const [step, setStep] = useState<'designs' | 'slots' | 'details'>('designs')
  const [clientForm, setClientForm] = useState<ClientForm>({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    notes: '',
  })
  const [formErrors, setFormErrors] = useState<Record<string, string | undefined>>({})
  const [isPending, startTransition] = useTransition()

  // Load event
  const { data: eventData, isLoading: eventLoading, error: eventError } = useQuery<{ data: EventPublic }>({
    queryKey: ['public', 'flash-event', studioSlug, eventSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/flash/${studioSlug}/${eventSlug}`)
      if (!res.ok) throw new Error('Event not found')
      return res.json() as Promise<{ data: EventPublic }>
    },
  })

  // Load slots
  const { data: slotsData, isLoading: slotsLoading } = useQuery<{ data: SlotPublic[] }>({
    queryKey: ['public', 'flash-slots', eventData?.data.id],
    queryFn: async () => {
      const res = await fetch(`/api/public/flash/${studioSlug}/${eventSlug}/slots`)
      if (!res.ok) throw new Error('Failed to load slots')
      return res.json() as Promise<{ data: SlotPublic[] }>
    },
    enabled: !!eventData?.data.id,
    refetchInterval: 30_000, // refresh every 30s to catch reservations expiring
  })

  // Load studio (for brand color)
  const { data: studioData } = useQuery<{ data: StudioPublic }>({
    queryKey: ['public', 'studio', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}`)
      if (!res.ok) throw new Error('Studio not found')
      return res.json() as Promise<{ data: StudioPublic }>
    },
  })

  const event = eventData?.data
  const slots = slotsData?.data ?? []
  const studio = studioData?.data
  const brandColor = studio?.brand_color ?? null

  // Determine which slots to show (may filter by selected design if designs exist)
  const hasDesigns = (event?.designs?.length ?? 0) > 0

  const eventDateFormatted = event
    ? new Date(event.event_date + 'T00:00:00').toLocaleDateString('en-US', {
        weekday: 'long',
        month: 'long',
        day: 'numeric',
      })
    : ''

  const validateForm = useCallback((): boolean => {
    const result = ClientSchema.safeParse(clientForm)
    if (!result.success) {
      const errors: Record<string, string | undefined> = {}
      result.error.issues.forEach((issue) => {
        const key = issue.path[0] as keyof ClientForm
        if (!errors[key]) errors[key] = issue.message
      })
      setFormErrors(errors)
      return false
    }
    setFormErrors({})
    return true
  }, [clientForm])

  function handleReserve() {
    if (!validateForm()) return
    if (!selectedSlotId) {
      toast.error('Please select a time slot')
      return
    }

    startTransition(async () => {
      const res = await fetch('/api/public/flash/reserve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          studioSlug,
          eventSlug,
          slotId: selectedSlotId,
          designId: selectedDesignId ?? undefined,
          clientInfo: {
            firstName: clientForm.firstName,
            lastName: clientForm.lastName || undefined,
            email: clientForm.email,
            phone: clientForm.phone || undefined,
            notes: clientForm.notes || undefined,
          },
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        if (res.status === 409) {
          toast.error('That slot is no longer available. Please choose another time.')
          setSelectedSlotId(null)
          setStep('slots')
        } else {
          toast.error(err.error ?? 'Failed to reserve slot')
        }
        return
      }

      const { data } = await res.json() as { data: { bookingToken: string } }

      // If deposit required, redirect to deposit checkout; otherwise directly to confirmation
      if ((event?.deposit_cents ?? 0) > 0) {
        const checkoutRes = await fetch('/api/public/deposits/checkout', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ booking_token: data.bookingToken }),
        })
        if (checkoutRes.ok) {
          const { data: checkoutData } = await checkoutRes.json() as { data: { checkoutUrl: string } }
          window.location.href = checkoutData.checkoutUrl
        } else {
          // No deposit checkout configured — go straight to confirmation
          router.push(`/book/${studioSlug}/flash/${eventSlug}/confirmation/${data.bookingToken}`)
        }
      } else {
        router.push(`/book/${studioSlug}/flash/${eventSlug}/confirmation/${data.bookingToken}`)
      }
    })
  }

  if (eventError) {
    return (
      <div className="min-h-svh flex items-center justify-center p-6">
        <div className="text-center space-y-3">
          <p className="text-lg font-semibold">Event not found</p>
          <p className="text-sm text-muted-foreground">
            This flash event is no longer available or has not been published yet.
          </p>
        </div>
      </div>
    )
  }

  return (
    <div
      className="min-h-svh"
      style={brandColor ? ({ '--booking-brand': brandColor } as React.CSSProperties) : undefined}
    >
      {/* Hero */}
      {eventLoading ? (
        <div className="h-52 bg-muted animate-pulse" />
      ) : (
        <div
          className="relative"
          style={
            brandColor
              ? { background: `linear-gradient(135deg, ${brandColor}20, ${brandColor}08)` }
              : undefined
          }
        >
          {event?.cover_image_url && (
            <div className="relative h-48 overflow-hidden">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={event.cover_image_url}
                alt={event.title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-background/80 to-transparent" />
            </div>
          )}
          <div className="max-w-lg mx-auto px-4 py-6">
            {studio?.logo_url && (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={studio.logo_url}
                alt={studio.name}
                className="h-8 object-contain mb-3"
              />
            )}
            <Typography variant="display" as="h1" className="text-2xl">
              {event?.title}
            </Typography>
            {event?.description && (
              <p className="mt-2 text-sm text-muted-foreground">{event.description}</p>
            )}

            {/* Meta row */}
            <div className="mt-3 flex flex-wrap gap-3 text-xs text-muted-foreground">
              <span className="flex items-center gap-1">
                <CalendarDays className="h-3 w-3" />
                {eventDateFormatted}
              </span>
              <span className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {event?.start_time.slice(0, 5)} – {event?.end_time.slice(0, 5)}
              </span>
              {event?.artist && (
                <span className="flex items-center gap-1">
                  <User className="h-3 w-3" />
                  {event.artist.display_name}
                </span>
              )}
              {event?.location && (
                <span className="flex items-center gap-1">
                  <MapPin className="h-3 w-3" />
                  {event.location.name}
                </span>
              )}
              {event && event.slot_price_cents > 0 && (
                <Badge variant="outline" className="text-[10px]">
                  {formatCurrency(event.slot_price_cents)} per slot
                </Badge>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Trust badges */}
      <div className="border-y border-border/30 bg-muted/20 py-3">
        <TrustBadges className="max-w-lg mx-auto px-4" />
      </div>

      {/* Main content */}
      <div className="max-w-lg mx-auto px-4 py-6 space-y-8">

        {/* Step 1: Designs (optional — skip if no designs) */}
        {hasDesigns && step === 'designs' && (
          <section className="space-y-4">
            <Typography variant="h2">Choose a design</Typography>
            <div className="grid grid-cols-2 gap-3">
              {event?.designs.map((design) => (
                <button
                  key={design.id}
                  disabled={design.sold_out}
                  className={cn(
                    'relative rounded-xl border text-left overflow-hidden transition-all',
                    design.sold_out
                      ? 'opacity-40 cursor-not-allowed border-border/40'
                      : selectedDesignId === design.id
                        ? 'border-primary ring-2 ring-primary/20'
                        : 'border-border/60 hover:border-primary/40'
                  )}
                  onClick={() => !design.sold_out && setSelectedDesignId(design.id)}
                >
                  <div className="aspect-square bg-muted overflow-hidden">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={design.image_url}
                      alt={design.title}
                      className="h-full w-full object-cover"
                    />
                  </div>
                  <div className="p-2 space-y-0.5">
                    <p className="text-xs font-semibold line-clamp-1">{design.title}</p>
                    {design.size_description && (
                      <p className="text-[10px] text-muted-foreground">{design.size_description}</p>
                    )}
                    {design.price_cents != null && (
                      <p className="text-[10px] font-medium">{formatCurrency(design.price_cents)}</p>
                    )}
                    {design.sold_out && (
                      <Badge variant="destructive" className="text-[9px] px-1">Sold out</Badge>
                    )}
                  </div>
                  {selectedDesignId === design.id && (
                    <div className="absolute top-1.5 right-1.5 h-5 w-5 rounded-full bg-primary flex items-center justify-center">
                      <Check className="h-3 w-3 text-primary-foreground" />
                    </div>
                  )}
                </button>
              ))}
            </div>

            <div className="flex gap-2">
              <Button
                disabled={!selectedDesignId}
                onClick={() => setStep('slots')}
                className="flex-1"
              >
                Continue to time slots
              </Button>
              <Button
                variant="outline"
                onClick={() => {
                  setSelectedDesignId(null)
                  setStep('slots')
                }}
              >
                Skip
              </Button>
            </div>
          </section>
        )}

        {/* Step 2: Slots */}
        {(step === 'slots' || (!hasDesigns && step === 'designs')) && (
          <section className="space-y-4">
            {hasDesigns && (
              <div className="flex items-center gap-2">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setStep('designs')}
                  className="h-7 px-2 text-xs"
                >
                  <ChevronLeft className="h-3.5 w-3.5 mr-1" />
                  Change design
                </Button>
                {selectedDesignId && (
                  <Badge variant="outline" className="text-[10px]">
                    {event?.designs.find((d) => d.id === selectedDesignId)?.title}
                  </Badge>
                )}
              </div>
            )}

            <Typography variant="h2">Pick a time slot</Typography>

            {slotsLoading ? (
              <div className="grid grid-cols-3 gap-2">
                {Array.from({ length: 9 }).map((_, i) => (
                  <Skeleton key={i} className="h-12 rounded-lg" />
                ))}
              </div>
            ) : slots.length === 0 ? (
              <div className="py-8 text-center">
                <p className="text-sm text-muted-foreground">
                  No available slots found for this event.
                </p>
              </div>
            ) : (
              <SlotGrid
                slots={slots}
                selected={selectedSlotId}
                onSelect={setSelectedSlotId}
              />
            )}

            <Button
              disabled={!selectedSlotId}
              onClick={() => setStep('details')}
              className="w-full"
            >
              Continue with selected slot
            </Button>
          </section>
        )}

        {/* Step 3: Client details */}
        {step === 'details' && (
          <section className="space-y-5">
            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setStep('slots')}
                className="h-7 px-2 text-xs"
              >
                <ChevronLeft className="h-3.5 w-3.5 mr-1" />
                Change slot
              </Button>
              {selectedSlotId && (
                <Badge variant="outline" className="text-[10px]">
                  {(() => {
                    const slot = slots.find((s) => s.id === selectedSlotId)
                    return slot
                      ? new Date(slot.slot_start).toLocaleTimeString('en-US', {
                          hour: '2-digit',
                          minute: '2-digit',
                        })
                      : ''
                  })()}
                </Badge>
              )}
            </div>

            <Typography variant="h2">Your details</Typography>

            {/* Summary card */}
            <div className="rounded-lg bg-muted/40 border border-border/60 p-3 space-y-1 text-sm">
              <p className="font-medium text-xs text-muted-foreground uppercase tracking-wide">
                Booking summary
              </p>
              <p className="font-medium">{event?.title}</p>
              {selectedSlotId && (() => {
                const slot = slots.find((s) => s.id === selectedSlotId)
                if (!slot) return null
                return (
                  <p className="text-xs text-muted-foreground tabular-nums">
                    {new Date(slot.slot_start).toLocaleString('en-US', {
                      weekday: 'short',
                      month: 'short',
                      day: 'numeric',
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </p>
                )
              })()}
              {event && event.slot_price_cents > 0 && (
                <p className="font-medium tabular-nums">{formatCurrency(event.slot_price_cents)}</p>
              )}
              {event && event.deposit_cents > 0 && (
                <p className="text-xs text-warning dark:text-warning-foreground">
                  Deposit required: {formatCurrency(event.deposit_cents)}
                </p>
              )}
            </div>

            {/* Client form */}
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="fe-first" className="text-xs">First name *</Label>
                  <Input
                    id="fe-first"
                    value={clientForm.firstName}
                    onChange={(e) => {
                      setClientForm((p) => ({ ...p, firstName: e.target.value }))
                      if (formErrors.firstName) setFormErrors((p) => ({ ...p, firstName: undefined }))
                    }}
                    placeholder="Jane"
                    className={cn('text-sm', formErrors.firstName && 'border-destructive')}
                  />
                  {formErrors.firstName && (
                    <p className="text-xs text-destructive">{formErrors.firstName}</p>
                  )}
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="fe-last" className="text-xs">Last name</Label>
                  <Input
                    id="fe-last"
                    value={clientForm.lastName}
                    onChange={(e) => setClientForm((p) => ({ ...p, lastName: e.target.value }))}
                    placeholder="Doe"
                    className="text-sm"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="fe-email" className="text-xs">Email *</Label>
                <Input
                  id="fe-email"
                  type="email"
                  value={clientForm.email}
                  onChange={(e) => {
                    setClientForm((p) => ({ ...p, email: e.target.value }))
                    if (formErrors.email) setFormErrors((p) => ({ ...p, email: undefined }))
                  }}
                  placeholder="jane@example.com"
                  className={cn('text-sm', formErrors.email && 'border-destructive')}
                />
                {formErrors.email && (
                  <p className="text-xs text-destructive">{formErrors.email}</p>
                )}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="fe-phone" className="text-xs">Phone</Label>
                <Input
                  id="fe-phone"
                  type="tel"
                  value={clientForm.phone}
                  onChange={(e) => setClientForm((p) => ({ ...p, phone: e.target.value }))}
                  placeholder="+1 (555) 000-0000"
                  className="text-sm"
                />
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="fe-notes" className="text-xs">Notes (optional)</Label>
                <Input
                  id="fe-notes"
                  value={clientForm.notes}
                  onChange={(e) => setClientForm((p) => ({ ...p, notes: e.target.value }))}
                  placeholder="Any notes for the artist..."
                  className="text-sm"
                />
              </div>
            </div>

            {/* Deposit notice */}
            {event && event.deposit_cents > 0 && (
              <div className="rounded-lg border border-warning/20 bg-warning/5 p-3">
                <p className="text-sm font-medium text-warning-foreground">
                  Deposit required: {formatCurrency(event.deposit_cents)}
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  You&apos;ll be redirected to pay the deposit to confirm your slot.
                </p>
              </div>
            )}

            {/* Spacer */}
            <div className="h-20 sm:h-0" />
          </section>
        )}
      </div>

      {/* Sticky bottom CTA — only on details step */}
      {step === 'details' && (
        <div
          className="fixed bottom-0 left-0 right-0 bg-background border-t border-border/40 px-4 py-3 flex gap-3 sm:relative sm:bottom-auto sm:bg-transparent sm:border-t-0 sm:px-0 sm:py-0"
          style={{ paddingBottom: 'max(0.75rem, env(safe-area-inset-bottom))' }}
        >
          <Button
            variant="outline"
            size="sm"
            onClick={() => setStep('slots')}
          >
            <ChevronLeft className="h-4 w-4 mr-1" />
            Back
          </Button>
          <Button
            className="flex-1"
            disabled={isPending}
            onClick={handleReserve}
          >
            {isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            {event && event.deposit_cents > 0 ? 'Pay deposit & confirm' : 'Confirm booking'}
          </Button>
        </div>
      )}
    </div>
  )
}

// ── Slot grid ─────────────────────────────────────────────────────────────────

function SlotGrid({
  slots,
  selected,
  onSelect,
}: {
  slots: SlotPublic[]
  selected: string | null
  onSelect: (id: string) => void
}) {
  return (
    <div className="grid grid-cols-3 gap-2">
      {slots.map((slot) => {
        const isOpen = slot.status === 'open'
        const isBooked = slot.status === 'booked'
        const isReserved = slot.status === 'reserved'
        const isBlocked = slot.status === 'blocked'
        const isSelected = selected === slot.id

        const time = new Date(slot.slot_start).toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
        })

        return (
          <button
            key={slot.id}
            disabled={!isOpen}
            onClick={() => isOpen && onSelect(slot.id)}
            className={cn(
              'relative rounded-lg border p-3 text-center text-xs font-medium transition-all',
              isSelected
                ? 'border-primary bg-primary text-primary-foreground'
                : isOpen
                  ? 'border-primary/30 text-foreground hover:border-primary hover:bg-primary/5'
                  : isReserved
                    ? 'border-border/40 bg-muted/40 text-muted-foreground cursor-not-allowed'
                    : isBooked
                      ? 'border-border/20 bg-muted/20 text-muted-foreground/50 cursor-not-allowed line-through'
                      : isBlocked
                        ? 'border-border/20 bg-muted/10 text-muted-foreground/40 cursor-not-allowed'
                        : 'border-border/40 text-muted-foreground cursor-not-allowed'
            )}
          >
            {time}
            {isSelected && (
              <span className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-primary flex items-center justify-center">
                <Check className="h-2.5 w-2.5 text-primary-foreground" />
              </span>
            )}
            {(isBooked || isBlocked) && (
              <span className="block text-[9px] text-muted-foreground/60 mt-0.5">
                {isBooked ? 'Taken' : 'N/A'}
              </span>
            )}
            {isReserved && (
              <span className="block text-[9px] text-muted-foreground/60 mt-0.5">Held</span>
            )}
          </button>
        )
      })}
    </div>
  )
}

'use client'

import { use } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Typography } from '@/components/ui/typography'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { CheckCircle2, CalendarFold, Clock, Zap, Mail } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'
import { DepositCheckoutButton } from '@/components/book/DepositCheckoutButton'
import { DepositConfirmationPoller } from '@/components/book/DepositConfirmationPoller'

interface BookingConfirmation {
  booking_token: string
  scheduled_at: string
  duration_min: number
  status: string
  price_cents: number
  deposit_cents: number
  deposit_paid: boolean
  studio: { name: string; slug: string; logo_url: string | null }
  artist: { display_name: string }
  service: { name: string } | null
  client: { first_name: string; last_name: string; email: string }
  metadata: { flash_event_id?: string; flash_event_slug?: string } | null
}

export default function FlashBookingConfirmationPage({
  params,
}: {
  params: Promise<{ studioSlug: string; eventSlug: string; token: string }>
}) {
  const { studioSlug, token } = use(params)
  const searchParams = useSearchParams()
  const depositJustPaid = searchParams.get('deposit_paid') === '1'

  const { data, isLoading, error, refetch } = useQuery<{ data: BookingConfirmation }>({
    queryKey: ['public', 'booking', token],
    queryFn: async () => {
      const res = await fetch(`/api/public/bookings/${token}`)
      if (!res.ok) throw new Error('Booking not found')
      return res.json() as Promise<{ data: BookingConfirmation }>
    },
    staleTime: 5 * 60_000,
  })

  const booking = data?.data

  if (error) {
    return (
      <div className="min-h-svh flex items-center justify-center p-6">
        <div className="text-center space-y-3">
          <p className="text-lg font-semibold">Booking not found</p>
          <p className="text-sm text-muted-foreground">
            We couldn&apos;t find a booking with this reference.
          </p>
          <Button
            variant="outline"
            size="sm"
            onClick={() => { window.location.href = `/book/${studioSlug}` }}
          >
            Back to booking
          </Button>
        </div>
      </div>
    )
  }

  if (isLoading || !booking) {
    return (
      <div className="max-w-lg mx-auto px-4 py-10 space-y-4">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-32 w-full" />
        <Skeleton className="h-16 w-full" />
      </div>
    )
  }

  const scheduledDate = new Date(booking.scheduled_at)
  const showDepositButton = booking.deposit_cents > 0 && !booking.deposit_paid && !depositJustPaid

  return (
    <div className="min-h-svh">
      <div className="max-w-lg mx-auto px-4 py-10 space-y-6">
        {/* Success hero */}
        <div className="text-center space-y-3">
          <div className="inline-flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
            <CheckCircle2 className="h-8 w-8 text-primary" />
          </div>
          <Typography variant="h1" className="text-xl">
            {depositJustPaid || booking.deposit_paid
              ? 'Slot confirmed!'
              : 'Slot reserved!'}
          </Typography>
          <p className="text-sm text-muted-foreground">
            {depositJustPaid || booking.deposit_paid
              ? `See you at ${booking.studio.name}.`
              : booking.deposit_cents > 0
                ? 'Your slot is held for 15 minutes. Pay the deposit to confirm.'
                : `Your slot is confirmed at ${booking.studio.name}.`}
          </p>
        </div>

        {/* Booking summary card */}
        <div className="rounded-xl border border-border/60 bg-card overflow-hidden">
          <div className="p-4 space-y-3">
            <div className="flex items-center gap-2">
              <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center">
                <Zap className="h-4 w-4 text-primary" />
              </div>
              <div>
                <p className="text-xs text-muted-foreground">{booking.studio.name}</p>
                <p className="font-semibold text-sm">Flash Day Slot</p>
              </div>
            </div>

            <div className="space-y-2 pt-1 border-t border-border/30">
              <div className="flex items-center gap-2 text-sm">
                <CalendarFold className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                {scheduledDate.toLocaleDateString('en-US', {
                  weekday: 'long',
                  month: 'long',
                  day: 'numeric',
                })}
              </div>
              <div className="flex items-center gap-2 text-sm">
                <Clock className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                {scheduledDate.toLocaleTimeString('en-US', {
                  hour: '2-digit',
                  minute: '2-digit',
                })}
                {' '}&middot;{' '}{booking.duration_min} min with {booking.artist.display_name}
              </div>
              <div className="flex items-center gap-2 text-sm">
                <Mail className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                Confirmation to {booking.client.email}
              </div>
            </div>

            {booking.price_cents > 0 && (
              <div className="flex justify-between text-sm border-t border-border/30 pt-3">
                <span className="text-muted-foreground">Total</span>
                <span className="font-semibold tabular-nums">
                  {formatCurrency(booking.price_cents)}
                </span>
              </div>
            )}
          </div>
        </div>

        {/* Deposit payment */}
        {showDepositButton && (
          <div className="space-y-3">
            <div className="rounded-lg border border-warning/20 bg-warning/5 p-3">
              <p className="text-sm font-medium text-warning-foreground">
                Deposit required: {formatCurrency(booking.deposit_cents)}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                Pay now to lock in your slot. Your reservation expires in 15 minutes.
              </p>
            </div>
            <DepositCheckoutButton
              bookingToken={token}
              depositCents={booking.deposit_cents}
            />
          </div>
        )}

        {/* Deposit poller — auto-refresh after payment */}
        {booking.deposit_cents > 0 && !booking.deposit_paid && !depositJustPaid && (
          <DepositConfirmationPoller
            bookingToken={token}
            onConfirmed={() => { void refetch() }}
          />
        )}

        <Button
          variant="outline"
          className="w-full"
          onClick={() => { window.location.href = `/book/${studioSlug}` }}
        >
          Back to {booking.studio.name}
        </Button>
      </div>
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getFlashEventBySlug } from '@/lib/flash-events/queries'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

/**
 * GET /api/public/flash/[studioSlug]/[eventSlug]
 * Returns a published+public flash event with designs and slot summary.
 * Anon-accessible. Rate-limited.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ studioSlug: string; eventSlug: string }> }
) {
  const ip = getClientIp(request)
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { studioSlug, eventSlug } = await params

  try {
    const event = await getFlashEventBySlug(studioSlug, eventSlug)

    if (!event) {
      return NextResponse.json({ error: 'Event not found' }, { status: 404 })
    }

    return NextResponse.json({ data: event })
  } catch (err) {
    logger.error({ err, studioSlug, eventSlug }, 'public flash event GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

/**
 * GET /api/public/flash/[studioSlug]/[eventSlug]/slots
 * Returns time slots (status + start/end only — no PII) for a published event.
 * Anon-accessible. Rate-limited.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ studioSlug: string; eventSlug: string }> }
) {
  const ip = getClientIp(request)
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { studioSlug, eventSlug } = await params
  const supabase = createPublicClient()

  try {
    // Resolve studio slug → id
    const { data: studio } = await supabase
      .from('studios')
      .select('id')
      .eq('slug', studioSlug)
      .maybeSingle()

    if (!studio) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    // Resolve event (must be public + published)
    const { data: event } = await supabase
      .from('flash_events')
      .select('id')
      .eq('studio_id', studio.id)
      .eq('slug', eventSlug)
      .eq('public', true)
      .eq('status', 'published')
      .maybeSingle()

    if (!event) {
      return NextResponse.json({ error: 'Event not found' }, { status: 404 })
    }

    // Slots — return only safe fields (no booking PII)
    const { data: slots, error } = await supabase
      .from('flash_event_slots')
      .select('id, slot_start, slot_end, status, design_id')
      .eq('flash_event_id', event.id)
      .order('slot_start', { ascending: true })

    if (error) {
      logger.error({ error, studioSlug, eventSlug }, 'public flash slots GET failed')
      return NextResponse.json({ error: 'Failed to load slots' }, { status: 500 })
    }

    return NextResponse.json({ data: slots ?? [] })
  } catch (err) {
    logger.error({ err, studioSlug, eventSlug }, 'public flash slots GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { publicBookingCreateRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { reserveSlot } from '@/lib/flash-events/mutations'
import { logger } from '@/lib/logger'

const ReserveBodySchema = z.object({
  studioSlug: z.string().min(1).max(100),
  eventSlug: z.string().min(1).max(100),
  slotId: z.string().uuid(),
  designId: z.string().uuid().optional(),
  clientInfo: z.object({
    firstName: z.string().min(1).max(100),
    lastName: z.string().max(100).optional(),
    email: z.string().email().max(254),
    phone: z.string().max(30).optional(),
    notes: z.string().max(2000).optional(),
  }),
})

/**
 * POST /api/public/flash/reserve
 * Atomically reserves a flash slot and creates a pending booking.
 * Anonymous endpoint — rate-limited to 10 requests per 10 minutes.
 */
export async function POST(request: NextRequest) {
  const ip = getClientIp(request)
  const { success } = await publicBookingCreateRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests — try again shortly' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ReserveBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { studioSlug, eventSlug, slotId, clientInfo } = parsed.data

  try {
    const result = await reserveSlot(studioSlug, eventSlug, slotId, {
      firstName: clientInfo.firstName,
      lastName: clientInfo.lastName,
      email: clientInfo.email,
      phone: clientInfo.phone,
      notes: clientInfo.notes,
    })

    if (!result.success) {
      const status = result.error.includes('unavailable') ? 409 : 400
      return NextResponse.json({ error: result.error }, { status })
    }

    return NextResponse.json(
      {
        data: {
          bookingToken: result.bookingToken,
          bookingId: result.bookingId,
          slotId: result.slotId,
        },
      },
      { status: 201 }
    )
  } catch (err) {
    logger.error({ err, studioSlug, eventSlug, slotId }, 'public flash reserve POST failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

